(function () {
  try {
    var u = JSON.parse(localStorage.getItem('user') || 'null') || { type: 'object', data: {} };
    u.data = u.data || {};
    u.data.token = 'local-verify-token';
    u.data.isAuth = true;
    u.data.identities = [{ id: 1 }];
    localStorage.setItem('user', JSON.stringify(u));
  } catch (e) {}

  var MOCK = JSON.stringify({ code: 200, data: {}, msg: 'ok' });
  var _open = XMLHttpRequest.prototype.open;
  XMLHttpRequest.prototype.open = function () {
    this.__mock = true;
    return _open.apply(this, arguments);
  };
  var _send = XMLHttpRequest.prototype.send;
  XMLHttpRequest.prototype.send = function () {
    if (this.__mock) {
      var self = this;
      Object.defineProperty(self, 'readyState', { get: function () { return 4; }, configurable: true });
      Object.defineProperty(self, 'status', { get: function () { return 200; }, configurable: true });
      Object.defineProperty(self, 'responseText', { get: function () { return MOCK; }, configurable: true });
      Object.defineProperty(self, 'response', { get: function () { return MOCK; }, configurable: true });
      setTimeout(function () { self.onreadystatechange && self.onreadystatechange(); self.onload && self.onload(); }, 10);
      return;
    }
    return _send.apply(this, arguments);
  };
  window.fetch = function () {
    return Promise.resolve(new Response(MOCK, { status: 200, headers: { 'Content-Type': 'application/json' } }));
  };
})();

